pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Use a caller address that will call Bank.supportsToken without reverting
        address caller = address(0xdead);
        // Deploy Bank and set caller's code to a Bank that returns true
        Bank bank = new Bank();
        // The caller must be the Bank contract itself for the supportsToken modifier to pass
        // So we prank the Bank contract address
        vm.prank(address(bank));
        // First, set the caller's balance to 1 by calling airDrop once (should succeed in reference)
        vm.prank(address(bank));
        c.airDrop();
        // Now tokenBalance[b] = 20; actually we need tokenBalance == 1 for the bug case
        // So let's reset: use a fresh address that we control
        address user = address(0xbeef);
        // Simulate Bank(user) being a valid contract returning true
        // Actually the supportsToken modifier checks Bank(msg.sender).supportsToken()
        // So msg.sender must be a contract that returns the expected bytes32
        // We'll deploy a Bank at user's address via vm.etch? Not allowed.
        // Instead, we use the Bank address as caller and set its tokenBalance via the contract
        // The challenge: tokenBalance is a mapping for each caller.
        // We'll use address(this) as the caller, but Test doesn't inherit Bank.
        // Simpler: just use a scenario where the caller is an externally owned account that has tokenBalance == 1
        // But the modifier supportsToken reverts if msg.sender is not a Bank contract.
        // To avoid that, we can replace the supportsToken modifier? No, contract is fixed.
        // We must use a Bank contract as msg.sender.
        // Deploy Bank and call airDrop via prank(Bank address).
        // But then tokenBalance[bank] gets incremented.
        // That's fine: we can work with bank address.
        address bankAddr = address(bank);
        vm.prank(bankAddr);
        c.airDrop(); // tokenBalance[bankAddr] = 20
        // Now tokenBalance[bankAddr] is NOT 1, so the bug version's hasNoBalance require fails
        // For the test to fail on bug version, we need tokenBalance[bankAddr] == 1
        // We can't directly set the mapping, so this approach is problematic.

        // Alternative: instead of using hasNoBalance, we can test the assertion directly:
        // The reference's hasNoBalance requires balance == 0, bug version requires balance == 1.
        // Choose a caller with balance == 0: then reference passes, bug reverts because require(0==1) fails.
        // So we don't need any state setup.
        // Just call airDrop from a fresh address that has balance 0 and is a Bank.
        // Deploy new Bank for each call
        Bank bank2 = new Bank();
        vm.prank(address(bank2));
        bool ok;
        try c.airDrop() {
            ok = true;
        } catch {
            ok = false;
        }
        // Reference: ok = true (balance 0 passes hasNoBalance)
        // Bug: ok = false (balance 0 != 1 reverts)
        assertTrue(ok);
    }
}

